// Data for the software SHA-256d that the original ESP32's hardware loop runs
// in its idle cycles (hw_sha_fill.S, generated by tools/hw_fill/gen_hw_fill.py).
// Portable (std C++ only) so the generated code can be checked on a PC.
//
// The software hash goes round by round through records of 5 words, one per
// round index i: A (the `a` register before round i), E (the `e` register),
// W (message word), KW (K[i] + W[i]) and K (the round constant). Round i reads
// records i-3..i and writes A, E of record i+1; it also expands W[i+16] (and
// KW[i+16]). The first hash (second header block) starts at round 3: rounds
// 0..2 do not depend on the nonce. The second hash stops after round 60, when
// the top 16 bits of the result are known.
#pragma once

#include <stdint.h>

namespace fill {

constexpr int kRecordWords = 5;  // A, E, W, KW, K
constexpr int kRecordBytes = kRecordWords * 4;
constexpr int kB1Records = 81;  // first hash: rounds 0..80
constexpr int kB2Records = 84;  // second hash: rounds -3..80
constexpr int kSteps = 62;      // rounds per hash done by the generated code

struct Buffers {
    uint32_t b1[kB1Records * kRecordWords];  // record i at i
    uint32_t b2[kB2Records * kRecordWords];  // record i at i + 3
    uint32_t mid[8];                         // state after the first 64 header bytes
    uint32_t c18;                            // W[18] of the first hash minus s0(W[3])
};

// Fills the buffers for an 80-byte header (nonce bytes ignored). Until the
// generated code has run one full nonce, the pending second-hash result is
// set so that it cannot look like a candidate.
void prepare(Buffers &buf, const uint8_t header[80]);

}  // namespace fill
